#!/usr/bin/env python3
"""Independent exact integer check of singleton profiles of noncrossing partitions."""
from math import comb
from fractions import Fraction

def catalan(n):
    return comb(2*n, n)//(n+1)

def partitions_rgs(n):
    """All ordinary set partitions, independently generated by restricted-growth words."""
    def rec(word, max_label):
        if len(word)==n:
            yield tuple(word)
            return
        for j in range(max_label+2):
            word.append(j)
            yield from rec(word, max(max_label,j))
            word.pop()
    yield from rec([0],0)

def is_noncrossing(w):
    n=len(w)
    for a in range(n):
        for b in range(a+1,n):
            for c in range(b+1,n):
                if w[a] != w[c]:continue
                for d in range(c+1,n):
                    if w[b] == w[d] and w[a] != w[b]:
                        return False
    return True

def direct_profile(w):
    cnt=[0]*(max(w)+1)
    for j in w:cnt[j]+=1
    return sum(1<<i for i,c in enumerate(w) if cnt[c]==1)

def fwht(a):
    a=list(a)
    n=len(a);h=1
    while h<n:
        for i in range(0,n,h*2):
            for j in range(i,i+h):
                u,v=a[j],a[j+h]
                a[j]=u+v
                a[j+h]=u-v
        h*=2
    return a

def theoretical_multiplier(n,w):
    return sum(comb(w,j)*(-2)**j*catalan(n-j) for j in range(w+1))


def exact_projection_norm(n,zeros):
    if not zeros:return Fraction(1)
    off=[int(i in zeros) for i in range(1<<n)]
    kernel=fwht(off)
    return Fraction((1<<n)-2*len(zeros)+sum(abs(x) for x in kernel),1<<n)


def run():
    checks=0
    for n in range(1,10):
        f=[0]*(1<<n); actual=0
        for p in partitions_rgs(n):
            if is_noncrossing(p):
                f[direct_profile(p)] += 1
                actual+=1
        assert actual==catalan(n),(n,actual,catalan(n))
        checks+=1
        trans=fwht(f)
        for mask,observed in enumerate(trans):
            expected=theoretical_multiplier(n,mask.bit_count())
            assert observed==expected,(n,mask,observed,expected)
            checks+=1
        zeros={i for i,v in enumerate(trans) if not v}
        wantzeros={s for s in range(1<<n) if n%2==0 and s.bit_count()==n-1}
        assert zeros==wantzeros
        checks+=1
        gap=min(abs(v) for v in trans if v)
        wantgap=catalan((n-1)//2) if n%2 else 2*catalan(n//2-1)
        assert gap==wantgap,(n,gap,wantgap)
        checks+=1
        norm=exact_projection_norm(n,zeros)
        if n%2:wantnorm=Fraction(1)
        else:wantnorm=Fraction(1)+Fraction(n*(comb(n,n//2)-2),1<<n)
        assert norm==wantnorm,(n,norm,wantnorm)
        checks+=1
        print(f'n={n} partitions={actual} zeros={len(zeros)} gap={gap} projection={norm}')
    for n in range(10,121):
        a=[theoretical_multiplier(n,w) for w in range(n+1)]
        assert [w for w,v in enumerate(a) if v==0] == ([n-1] if n%2==0 else [])
        checks+=n+1
        gap=min(abs(v) for v in a if v)
        target=catalan((n-1)//2) if n%2 else 2*catalan(n//2-1)
        assert gap==target,(n,gap,target)
        checks+=1
    print('PASS exact checks',checks)

if __name__=='__main__':run()
